def check_shape(
    self, check_obj, schema: DataArraySchema
) -> list[CoreCheckResult]:
    """Check positional shape."""
    results: list[CoreCheckResult] = []
    if schema.shape is None:
        return results
    for i, sh in enumerate(schema.shape):
        if sh is None:
            continue
        if i >= len(check_obj.shape) or check_obj.shape[i] != sh:
            results.append(
                CoreCheckResult(
                    passed=False,
                    check="shape",
                    reason_code=(SchemaErrorReason.MISMATCH_INDEX),
                    message=(
                        f"expected shape[{i}]={sh}, "
                        f"got shape "
                        f"{check_obj.shape}"
                    ),
                    failure_cases=str(check_obj.shape),
                )
            )
    return results

def scrape_url(self, args):
    """Scrape a single web page."""
    args = normalize_tool_input(args, tool_name='firecrawl')
    url = args.get('url')
    if not url:
        raise ValueError('scrape_url requires a `url` parameter')

    result = firecrawl_wrapper(lambda: self.IGlobal.app.scrape(url))

    fmt = args.get('format', 'markdown')
    content = getattr(result, fmt, None) or getattr(result, 'markdown', None) or ''
    if not isinstance(content, str):
        content = json.dumps(content)

    metadata = getattr(result, 'metadata', None)
    if metadata is not None and not isinstance(metadata, dict):
        try:
            metadata = metadata.model_dump(exclude_none=True) if hasattr(metadata, 'model_dump') else {}
        except Exception as e:
            warning(f'firecrawl: failed to dump metadata: {e}')
            metadata = {}

    return {'success': True, 'content': content, 'metadata': metadata or {}}

