def check_column_names_are_unique(
    self,
    check_obj: DataFrame,
    schema,
) -> CoreCheckResult:
    """Check for column name uniqueness."""

    passed = True
    failure_cases = None
    message = None

    if not schema.unique_column_names:
        return CoreCheckResult(
            passed=True,
            check="dataframe_column_labels_unique",
        )

    column_count_dict: dict[Any, Any] = {}
    failed = []
    for column_name in check_obj.columns:
        if column_count_dict.get(column_name):
            # Insert to the list only once
            if column_count_dict[column_name] == 1:
                failed.append(column_name)
            column_count_dict[column_name] += 1

        else:
            column_count_dict[column_name] = 0

    if failed:
        passed = False
        message = (
            f"dataframe contains multiple columns with label(s): {failed}"
        )
        failure_cases = failed

    return CoreCheckResult(
        passed=passed,
        check="dataframe_column_labels_unique",
        reason_code=SchemaErrorReason.DUPLICATE_COLUMN_LABELS,
        message=message,
        failure_cases=failure_cases,
    )

async def _write_image(self, posix_path: str, suffix: str) -> ToolResult:
        """Copy an image file to the clipboard as image data."""
        # Determine the AppleScript clipboard class.
        # PNG and TIFF have dedicated classes; everything else we
        # convert to TIFF via sips first (built into macOS).
        if suffix == ".png":
            as_class = "«class PNGf»"
        elif suffix in (".tiff", ".tif"):
            as_class = "«class TIFF»"
        else:
            # JPEG, GIF, BMP, WEBP — convert to PNG in-place (temp) via sips.
            # Actually it's simpler to just use JPEG class for .jpg and
            # fall back to converting others to PNG.
            if suffix in (".jpg", ".jpeg"):
                as_class = "«class JPEG»"
            else:
                # For GIF, BMP, WEBP: read as PNG via sips conversion to
                # a temp file, then copy that.
                import tempfile
                tmp = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
                tmp.close()
                try:
                    await asyncio.to_thread(
                        subprocess.run,
                        ["sips", "-s", "format", "png", posix_path, "--out", tmp.name],
                        capture_output=True,
                        timeout=_SUBPROCESS_TIMEOUT,
                    )
                    posix_path = tmp.name
                    as_class = "«class PNGf»"
                except Exception:
                    # Fall back to file reference if conversion fails.
                    return await self._write_file_ref(posix_path)

        script = f'set the clipboard to (read (POSIX file "{posix_path}") as {as_class})'
        try:
            await asyncio.to_thread(
                subprocess.run,
                ["osascript", "-e", script],
                capture_output=True,
                timeout=_SUBPROCESS_TIMEOUT,
                check=True,
            )
            return ToolResult(
                success=True,
                content=f"Copied image to clipboard: {Path(posix_path).name}",
            )
        except Exception as exc:
            return ToolResult(success=False, error=f"Failed to copy image to clipboard: {exc}")

def _run_automation_action(action, event, payload, dev_id, cfg, rule):
    """Run one rule action: queue a saved script on the event's device, or
    re-dispatch the event to a named webhook destination."""
    atype = (action or {}).get('type')
    if atype == 'run_script':
        sid = action.get('script_id')
        if not sid or not dev_id:
            return
        scripts = load(SCRIPTS_FILE) or {}
        body = next((s.get('body', '') for s in (scripts.get('scripts') or [])
                     if s.get('id') == sid), None)
        if not body:
            return
        # Queue exec exactly like the scheduler. Quarantine is enforced at the
        # command-dispatch chokepoint, so a quarantined host still won't run it.
        with _LockedUpdate(CMDS_FILE) as cmds:
            q = cmds.setdefault(dev_id, [])
            queued = f'exec:{body}'
            if queued not in q:
                q.append(queued)
        nm = ((load(DEVICES_FILE) or {}).get(dev_id) or {}).get('name', dev_id)
        log_command(f"automation({rule.get('name', 'rule')})", dev_id, nm, f"run_script:{sid}")
        audit_log('automation', 'rule_run_script',
                  f"rule={rule.get('id')} dev={dev_id} script={sid} on {event}")
    elif atype == 'notify':
        dest = next((d for d in (cfg.get('webhook_urls') or [])
                     if isinstance(d, dict) and d.get('id') == action.get('dest_id')), None)
        if not dest or not dest.get('url'):
            return
        safe = {k: v for k, v in (payload or {}).items() if not str(k).startswith('_')}
        try:
            msg = _webhook_message(event, payload or {})
        except Exception:
            msg = event
        _dispatch_one_webhook(event, dest, safe, msg,
                              _webhook_title(event), _webhook_priority(event))

async def _receive_loop(self) -> None:
        """Main WebSocket receive loop."""
        assert self._ws is not None
        try:
            async for raw_msg in self._ws:
                if raw_msg.type == aiohttp.WSMsgType.TEXT:
                    try:
                        data = json.loads(raw_msg.data)
                        await self._handle_message(data)
                    except json.JSONDecodeError as exc:
                        log.warning("Invalid JSON from BotPort: %s", exc)
                    except Exception as exc:
                        log.error("BotPort message handler error: %s", exc)

                elif raw_msg.type in (aiohttp.WSMsgType.ERROR, aiohttp.WSMsgType.CLOSED):
                    break

        except asyncio.CancelledError:
            return
        except Exception as exc:
            log.error("BotPort receive loop error: %s", exc)

        # Connection lost.
        self._connected = False
        log.warning("BotPort connection lost")
        if self._should_run:
            self._reconnect_task = asyncio.create_task(self._reconnect_loop())

def check_column_presence(
    self,
    check_obj: DataFrame,
    schema,
    column_info: ColumnInfo,
) -> list[CoreCheckResult]:
    """Check that all columns in the schema are present in the dataframe."""
    results = []
    if column_info.absent_column_names:
        for colname in column_info.absent_column_names:
            results.append(
                CoreCheckResult(
                    passed=False,
                    check="column_in_dataframe",
                    reason_code=SchemaErrorReason.COLUMN_NOT_IN_DATAFRAME,
                    message=(
                        f"column '{colname}' not in dataframe"
                        f" {check_obj.head()}"
                    ),
                    failure_cases=scalar_failure_case(colname),
                )
            )
    else:
        results.append(
            CoreCheckResult(
                passed=True,
                check="column_in_dataframe",
            )
        )
    return results

async def list_files(self, prefix: str = '') -> list:
    """List all files with given prefix."""
    try:
        if prefix:
            search_path = self._get_full_path(prefix)
        else:
            search_path = self._root_path

        files = []

        if search_path.exists():
            if search_path.is_file():
                # If prefix points to a file, return just that file
                relative_path = str(search_path.relative_to(self._root_path))
                files.append(relative_path.replace('\\', '/'))
            elif search_path.is_dir():
                # If prefix points to a directory, list all files recursively
                for item in search_path.rglob('*'):
                    if item.is_file():
                        relative_path = str(item.relative_to(self._root_path))
                        files.append(relative_path.replace('\\', '/'))

        return sorted(files)

    except Exception as e:
        raise StorageError(f'Failed to list files with prefix {prefix}: {e}') from e

