def append_tool_output(
        self,
        tool_name: str,
        arguments: dict[str, Any] | None,
        raw_output: str,
        render: bool = True,
    ) -> None:
        """Append raw tool output entry to monitor pane buffer."""
        args = arguments or {}
        args_text = ""
        if args:
            try:
                args_text = json.dumps(args, ensure_ascii=True, sort_keys=True)
            except Exception:
                args_text = str(args)
        header = f"{tool_name} {args_text}".strip()
        if tool_name == "cron" or bool(args.get("cron")):
            header = f"[CRON] {header}"
        body = self._format_monitor_tool_body(tool_name, raw_output).rstrip("\n")
        self._append_tool_text(f"{header}\n{body}\n\n")
        if render:
            self._render_monitor_view()
        # Update thinking indicator for non-silent tools (skip during history replay).
        if not getattr(self, "_replaying_history", False):
            normalized = str(tool_name or "").strip().lower()
            if normalized not in self._THINKING_SILENT_TOOLS:
                from captain_claw.agent_tool_loop_mixin import AgentToolLoopMixin
                summary = AgentToolLoopMixin._tool_thinking_summary(tool_name, args)
                self.set_thinking(summary, tool=tool_name, phase="tool")

def init(config: Any) -> bool:
    """Initialize the OpenAI subscription provider."""
    global _auth

    stored_auth = _load_tokens()
    if stored_auth is not None:
        if time.time() < stored_auth.expires_at - 300:
            _auth = stored_auth
            logger.info("OpenAI subscription provider initialized with stored tokens")
            return True

        if stored_auth.refresh_token:
            try:
                _auth = _refresh_access_token(stored_auth.refresh_token)
                logger.info(
                    "OpenAI subscription provider initialized with refreshed token"
                )
                return True
            except Exception as e:
                logger.debug(f"Token refresh failed during init: {e}")

    logger.info(
        "OpenAI subscription provider available "
        "(run 'gptme auth openai-subscription' to authenticate)"
    )
    return True

def _ensure_openai_compat_reasoning_stream(self) -> None:
    """Lazily build the raw openai client used to stream reasoning for
    OpenAI-compatible drivers (built here, since _llm exists after super().__init__).
    """
    if self._native_stream_provider or self._raw_openai_client is not None:
        return
    if not self._is_reasoning:
        return
    llm = getattr(self, '_llm', None)
    base_url = getattr(llm, 'openai_api_base', None)
    if llm is None or not base_url:
        return  # not an OpenAI-compatible driver (e.g. plain OpenAI, Anthropic)
    key = getattr(llm, 'openai_api_key', None)
    api_key = key.get_secret_value() if hasattr(key, 'get_secret_value') else key
    try:
        from openai import OpenAI

        self._raw_openai_client = OpenAI(api_key=api_key, base_url=str(base_url))
        self._native_stream_provider = 'openai_compat_reasoning'
    except Exception as e:  # openai SDK missing / bad client → fall back to generic stream
        debug(f'    Native reasoning stream unavailable: {type(e).__name__}: {e}')
